10	#ifndef ATB_SVECTOR_H
11	#define ATB_SVECTOR_H
12	#include <vector>
13	#include <cstddef>
14	#include <exception>
15	#include <stdexcept>
16	#include <utility>
17	#include <initializer_list>
18	
19	//!
20	//! \file svector.h
21	//!
22	//! \brief 定义加速库容器类
23	//!
24	
25	namespace atb {
26	//! \brief 最大容器大小
27	constexpr std::size_t MAX_SVECTOR_SIZE = 256;
28	//! \brief 默认容器大小
29	constexpr std::size_t DEFAULT_SVECTOR_SIZE = 64;
30	//! \brief 边界检查标志
31	constexpr bool CHECK_BOUND = true;
32	
33	struct MaxSizeExceeded : public std::exception {};
34	
35	//!
36	//! \class SVector
37	//!
38	//! \brief 加速库svector类
39	//!
40	//! 封装动态数组的顺序容器
41	//!
42	template <class T> class SVector {
43	public:
44	    //! \brief 默认构造函数
45	    //!
46	    //! \note 容量为DEFAULT_SVECTOR_SIZE
47	    //!
48	    constexpr SVector() : size_(0)
49	    {
50	        for (std::size_t i = 0; i < DEFAULT_SVECTOR_SIZE; ++i) {
51	            storage_[i] = {};
52	        }
53	    }
54	    //! \brief 初始化列表构造函数
55	    //!
56	    //! \param list
57	    //!
58	    //! \note list长度需小于MAX_SVECTOR_SIZE，否则会抛出异常
59	    //!
60	    SVector(std::initializer_list<T> list)
61	    {
62	        std::size_t listSize = list.size();
63	        if (listSize > MAX_SVECTOR_SIZE) {
64	            throw MaxSizeExceeded();
65	        }
66	        std::size_t i = 0;
67	        if (listSize > DEFAULT_SVECTOR_SIZE) {
68	            heap_ = reinterpret_cast<T *>(malloc(MAX_SVECTOR_SIZE * sizeof(T)));
69	            if (!heap_) {
70	                throw std::bad_alloc();
71	            }
72	            i = 0;
73	            for (auto it = list.begin(); it != list.end() && i < size_; ++it) {
74	                heap_[i++] = *it;
75	            }
76	            capacity_ = MAX_SVECTOR_SIZE;
77	            return;
78	        }
79	
80	        size_ = list.size();
81	        i = 0;
82	        for (auto it = list.begin(); it != list.end() && i < size_; ++it) {
83	            storage_[i++] = *it;
84	        }
85	    }
86	    //! \brief 带参数的构造函数
87	    //!
88	    //! \param size
89	    //! \param value
90	    //!
91	    //! \note size大小需小于MAX_SVECTOR_SIZE，否则会抛出异常
92	    //!
93	    explicit SVector(std::size_t size, const T &value = 0) : size_(size)
94	    {
95	        if (size > MAX_SVECTOR_SIZE) {
96	            throw MaxSizeExceeded();
97	        }
98	        if (size > DEFAULT_SVECTOR_SIZE) {
99	            heap_ = reinterpret_cast<T *>(malloc(MAX_SVECTOR_SIZE * sizeof(T)));
100	            if (!heap_) {
101	                throw std::bad_alloc();
102	            }
103	            for (std::size_t i = 0; i < size; ++i) {
104	                heap_[i] = value;
105	            }
106	            capacity_ = MAX_SVECTOR_SIZE;
107	            return;
108	        }
109	        for (std::size_t i = 0; i < size_; ++i) {
110	            storage_[i] = value;
111	        }
112	    }
113	    //! \brief 拷贝构造函数，创建一个新的SVector对象并将另一个SVector对象的值复制到新对象
114	    //!
115	    //! \param other
116	    //!
117	    SVector(const SVector<T> &other)
118	    {
119	        if (other.heap_) {
120	            heap_ = reinterpret_cast<T *>(malloc(other.size_ * sizeof(T)));
121	            if (!heap_) {
122	                throw std::bad_alloc();
123	            }
124	            size_ = other.size_;
125	            for (std::size_t i = 0; i < other.size_; ++i) {
126	                heap_[i] = other.heap_[i];
127	            }
128	        } else {
129	            size_ = other.size_;
130	            for (std::size_t i = 0; i < other.size_; ++i) {
131	                storage_[i] = other.storage_[i];
132	            }
133	        }
134	    }
135	
136	    ~SVector()
137	    {
138	        if (heap_) {
139	            free(heap_);
140	        }
141	    }
142	
143	    //! \brief 插入元素到指定容器
144	    //!
145	    //! \param val
146	    //!
147	    //! \note 待添加SVector内元素必须小于SVector容量，否则会抛出异常
148	    //!
149	    void push_back(const T &val) noexcept((!CHECK_BOUND) && std::is_nothrow_assignable<T, const T &>::value)
150	    {
151	        if (heap_) {
152	            if (CHECK_BOUND && size_ == capacity_) {
153	                throw MaxSizeExceeded();
154	            }
155	            heap_[size_++] = val;
156	            return;
157	        }
158	        if (CHECK_BOUND && size_ == DEFAULT_SVECTOR_SIZE) {
159	            if (!heap_) {
160	                MoveToHeap();
161	            }
162	            heap_[size_++] = val;
163	            return;
164	        }
165	        storage_[size_++] = val;
166	    }
167	
168	    //! \brief 获取容器起始元素地址
169	    //!
170	    //! \return 指针
171	    //!
172	    T *begin() noexcept
173	    {
174	        if (heap_) {
175	            return &heap_[0];
176	        }
177	        return &storage_[0];
178	    }
179	
180	    //! \brief 获取容器起始元素地址
181	    //!
182	    //! \return 常量指针
183	    //!
184	    const T *begin() const noexcept
185	    {
186	        if (heap_) {
187	            return &heap_[0];
188	        }
189	        return &storage_[0];
190	    }
191	
192	    //! \brief 获取容器尾元素地址
193	    //!
194	    //! \return 指针
195	    //!
196	    T *end() noexcept
197	    {
198	        if (heap_) {
199	            return (&heap_[0]) + size_;
200	        }
201	        return (&storage_[0]) + size_;
202	    }
203	
204	    //! \brief 获取容器尾地址
205	    //!
206	    //! \return 常量指针
207	    //!
208	    const T *end() const noexcept
209	    {
210	        if (heap_) {
211	            return (&heap_[0]) + size_;
212	        }
213	        return (&storage_[0]) + size_;
214	    }
215	
216	    //! \brief 访问指定位置的元素
217	    //!
218	    //! \param i
219	    //!
220	    //! \return 引用
221	    //!
222	    T &operator[](std::size_t i)
223	    {
224	        if (i >= size_) {
225	            throw std::out_of_range("SVector operator[] index out of range");
226	        }
227	        if (heap_) {
228	            return heap_[i];
229	        }
230	        if (i >= DEFAULT_SVECTOR_SIZE) {
231	            throw std::out_of_range("SVector operator[] index out of range of stack, and consider reserve first");
232	        }
233	        return storage_[i];
234	    }
235	
236	    //! \brief 访问指定位置的元素
237	    //!
238	    //! \param i
239	    //!
240	    //! \return 常量引用
241	    //!
242	    const T &operator[](std::size_t i) const
243	    {
244	        if (i >= size_) {
245	            throw std::out_of_range("SVector operator[] index out of range");
246	        }
247	        if (heap_) {
248	            return heap_[i];
249	        }
250	        if (i >= DEFAULT_SVECTOR_SIZE) {
251	            throw std::out_of_range("SVector operator[] index out of range of stack, and consider reserve first");
252	        }
253	        return storage_[i];
254	    }
255	
256	    //! \brief 访问指定位置的元素
257	    //!
258	    //! \param i
259	    //!
260	    //! \return 引用
261	    //!
262	    T &at(std::size_t i)
263	    {
264	        if (i >= size_) {
265	            throw std::out_of_range("SVector at index out of range");
266	        }
267	        if (heap_) {
268	            return heap_[i];
269	        }
270	        if (i >= DEFAULT_SVECTOR_SIZE) {
271	            throw std::out_of_range("SVector at() index out of range of stack, and consider reserve first");
272	        }
273	        return storage_[i];
274	    }
275	
276	    //! \brief 访问指定位置的元素
277	    //!
278	    //! \param i
279	    //!
280	    //! \return 引用
281	    //!
282	    const T &at(std::size_t i) const
283	    {
284	        if (i >= size_) {
285	            throw std::out_of_range("SVector at index out of range");
286	        }
287	        if (heap_) {
288	            return heap_[i];
289	        }
290	        if (i >= DEFAULT_SVECTOR_SIZE) {
291	            throw std::out_of_range("SVector at() index out of range of stack, and consider reserve first");
292	        }
293	        return storage_[i];
294	    }
295	
296	    //! \brief 获取容器的大小
297	    //!
298	    //! \return size
299	    //!
300	    std::size_t size() const noexcept
301	    {
302	        return size_;
303	    }
304	
305	    //! \brief 向容器内指定位置插入元素
306	    //!
307	    //! \param pos
308	    //! \param value
309	    //!
310	    //! \note pos必须小于SVector容量，否则会抛出异常
311	    //!
312	    void insert(const std::size_t pos, const T &value)
313	    {
314	        if (pos > size_) {
315	            throw std::out_of_range("SVector insert index out of stack range");
316	        }
317	        if (!heap_ && size_ == DEFAULT_SVECTOR_SIZE) {
318	            MoveToHeap();
319	        }
320	        if (heap_) {
321	            if (pos > size_ || pos == capacity_) {
322	                throw MaxSizeExceeded();
323	            }
324	            for (auto it = size_; it != pos; it--) {
325	                heap_[it] = heap_[it - 1];
326	            }
327	            heap_[pos] = value;
328	            size_ += 1;
329	            return;
330	        }
331	        for (auto it = size_; it != pos; it--) {
332	            storage_[it] = storage_[it - 1];
333	        }
334	        storage_[pos] = value;
335	        size_ += 1;
336	        return;
337	    }
338	
339	    //! \brief 判断容器是否为空
340	    //!
341	    //! \return bool值
342	    //!
343	    bool empty() const noexcept
344	    {
345	        return size_ == 0;
346	    }
347	
348	    //! \brief 清空容器
349	    void clear() noexcept
350	    {
351	        size_ = 0;
352	    }
353	
354	    //! \brief 获取容器起始元素地址
355	    //!
356	    //! \return 指针
357	    //!
358	    T *data() noexcept
359	    {
360	        if (heap_) {
361	            return &heap_[0];
362	        }
363	        return &storage_[0];
364	    }
365	
366	    //! \brief 获取容器起始元素地址
367	    //!
368	    //! \return 常量指针
369	    //!
370	    const T *data() const noexcept
371	    {
372	        if (heap_) {
373	            return &heap_[0];
374	        }
375	        return &storage_[0];
376	    }
377	
378	    //! \brief 改变SVector容器大小，不能改变SVector容量
379	    //!
380	    //! \param size
381	    //!
382	    //! \note 传入size参数不能超过SVector容量，反之，则会抛出异常。
383	    //!
384	    void resize(std::size_t size)
385	    {
386	        if ((size > MAX_SVECTOR_SIZE) || (heap_ && size > capacity_)) {
387	            throw MaxSizeExceeded();
388	        }
389	        if (!heap_ && size > DEFAULT_SVECTOR_SIZE) {
390	            MoveToHeap();
391	        }
392	        size_ = size;
393	    }
394	
