398	    //!
399	    //! \note 用于预分配内存空间，SVector默认容量为DEFAULT_SVECTOR_SIZE，传入的size需小于MAX_SVECTOR_SIZE，反之，则会抛出异常。
400	    //!
401	    void reserve(std::size_t size)
402	    {
403	        if (size > MAX_SVECTOR_SIZE) {
404	            throw MaxSizeExceeded();
405	        }
406	
407	        if (size > DEFAULT_SVECTOR_SIZE) {
408	            if (heap_) {
409	                free(heap_);
410	            }
411	            heap_ = reinterpret_cast<T *>(malloc(size * sizeof(T)));
412	            if (!heap_) {
413	                throw std::bad_alloc();
414	            }
415	            for (std::size_t i = 0; i < size; ++i) {
416	                heap_[i] = {};
417	            }
418	            capacity_ = size;
419	        }
