446	                }
447	            }
448	        }
449	        return true;
450	    }
451	
452	    //! \brief 判断两个容器中的元素是否存在不同
453	    //!
454	    //! \param other
455	    //!
456	    //! \return bool值
457	    //!
458	    bool operator!=(const SVector<T> &other) const
459	    {
460	        if (heap_) {
461	            if (size_ != other.size_ || !other.heap_) {
462	                return true;
463	            }
464	            for (std::size_t i = 0; i < size_; ++i) {
465	                if (heap_[i] != other.heap_[i]) {
466	                    return true;
467	                }
468	            }
469	        } else {
470	            if (size_ != other.size_) {
471	                return true;
472	            }
