474	                if (storage_[i] != other.storage_[i]) {
475	                    return true;
476	                }
477	            }
478	        }
479	        return false;
480	    }
481	
482	    //! \brief 判断一个容器中的元素是否比另一个容器小
483	    //!
484	    //! \param other
485	    //!
486	    //! \return bool值
487	    //!
488	    bool operator<(const SVector<T> &other) const
489	    {
490	        if (heap_) {
491	            if (size_ != other.size_ || !other.heap_) {
492	                return size_ < other.size_;
493	            }
494	            for (std::size_t i = 0; i < size_; ++i) {
495	                if (heap_[i] != other.heap_[i]) {
496	                    return heap_[i] < other.heap_[i];
497	                }
498	            }
499	        } else {
500	            if (size_ != other.size_) {
501	                return size_ < other.size_;
502	            }
