505	                    return storage_[i] < other.storage_[i];
506	                }
507	            }
508	        }
509	        return false;
510	    }
511	
512	    //! \brief 重载运算符函数，将初始化列表中的元素赋值给一个SVector对象
513	    //!
514	    //! \param list
515	    //!
516	    //! \return 容器引用
517	    //!
518	    SVector &operator=(std::initializer_list<T> list)
519	    {
