87	 * @return atb::Status atb错误码
88	 */
89	atb::Status CastOp(atb::Context *contextPtr, aclrtStream stream, const atb::Tensor inTensor,
90	                   const aclDataType outTensorType, atb::Tensor &outTensor)
91	{
92	    uint64_t workspaceSize = 0;
93	    void *workspace = nullptr;
94	    // 创建Elewise的ELEWISE_CAST
95	    atb::infer::ElewiseParam castParam;
96	    castParam.elewiseType = atb::infer::ElewiseParam::ELEWISE_CAST;
97	    castParam.outTensorType = outTensorType;
