111	    CHECK_STATUS(castOp->Execute(castVariantPack, (uint8_t *)workspace, workspaceSize, contextPtr));
112	    CHECK_STATUS(aclrtSynchronizeStream(stream)); // 流同步，等待device侧任务计算完成
113	    if (workspaceSize > 0) {
114	        CHECK_STATUS(aclrtFree(workspace)); // 清理工作空间
115	    }
116	    return atb::ErrorType::NO_ERROR;
117	}
