119	/**
120	 * @brief 根据输入inShape，判断是NZ格式的shape还是ND格式的shape，并得到两种格式下的shape
121	 * @param tensorType tensor的数据类型
122	 * @param inShape tensor的shape
123	 * @param ndShape ND格式tensor的shape
124	 * @param nzShape NZ格式tensor的shape
125	 * @return atb::Status atb错误码
126	 */
127	atb::Status GetShape(const aclDataType tensorType, const std::vector<int64_t> &inShape, std::vector<int64_t> &ndShape,
128	                     std::vector<int64_t> &nzShape)
129	{
130	    constexpr int64_t DIM_TRAN_PARAM_INT8 = 32;
131	    constexpr int64_t DIM_TRAN_PARAM_BF16_FP16 = 16;
132	    int64_t n0 = DIM_TRAN_PARAM_BF16_FP16; // 维度转换参数
133	    // 输入tensor数据类型为ACL_INT8时，维度转换参数取32
134	    if (tensorType == ACL_INT8) {
135	        n0 = DIM_TRAN_PARAM_INT8;
136	    }
137	    if (inShape.size() == 4) { // inShape是NZ格式tensor的shape
138	        nzShape.assign(inShape.begin(), inShape.end());
139	        ndShape = {inShape[0], inShape[2], inShape[1] * inShape[3]};
140	    } else { // inShape是ND格式tensor的shape
141	        ndShape.assign(inShape.begin(), inShape.end());
142	        if (inShape.size() == 3) { // 该shape包含batch参数
143	            nzShape = {inShape[0], inShape[2] / n0, inShape[1], n0};
144	        } else if (inShape.size() == 2) {
145	            nzShape = {1, inShape[1] / n0, inShape[0], n0};
146	        } else {
147	            std::cout << "shape dimensions invalid!" << std::endl;
148	            return atb::ErrorType::ERROR_INVALID_TENSOR_DIM_NUM;
149	        }
150	    }
151	    return atb::ErrorType::NO_ERROR;
152	}
